<?php declare(strict_types=1); namespace App\Http\Controllers\Api\V1\Admin; use App\Http\Controllers\Api\V1\Admin\Concerns\AuthorizesAdminAccess; use App\Http\Controllers\Controller; use App\Http\Requests\Admin\UpdateWorkflowTemplateRequest; use App\Http\Resources\Admin\WorkflowTemplateResource; use App\Models\WorkflowTemplate; use App\Services\Admin\WorkflowTemplateAdminService; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; final class AdminWorkflowTemplateController extends Controller { use AuthorizesAdminAccess; public function __construct(private WorkflowTemplateAdminService $service){} public function index(Request $r): JsonResponse { $this->authorizeAdmin('workflow.view'); $this->authorize('viewAny',WorkflowTemplate::class); return WorkflowTemplateResource::collection($this->service->paginate($r->only(['code','is_active']),(int)$r->integer('per_page',15)))->response(); } public function show(Request $r,int $id): JsonResponse { $t=$this->service->findOrFail($id,['definitions.department','transitions']); $this->authorizeAdmin('workflow.view'); $this->authorize('view',$t); return response()->json(['data'=>WorkflowTemplateResource::make($t)]); } public function update(UpdateWorkflowTemplateRequest $r,int $id): JsonResponse { $t=$this->service->findOrFail($id); $this->authorizeAdmin('workflow.manage'); $this->authorize('update',$t); return response()->json(['data'=>WorkflowTemplateResource::make($this->service->updateDraft($t,$r->validated(),$r->user())->load(['definitions.department','transitions']))]); } public function createDraft(Request $r,int $id): JsonResponse { $t=$this->service->findOrFail($id); $this->authorizeAdmin('workflow.manage'); $this->authorize('createDraft',$t); return response()->json(['data'=>WorkflowTemplateResource::make($this->service->createDraftFromPublished($t,$r->user()))],201);} public function publish(Request $r,int $id): JsonResponse { $t=$this->service->findOrFail($id); $this->authorizeAdmin('workflow.manage'); $this->authorize('publish',$t); return response()->json(['data'=>WorkflowTemplateResource::make($this->service->publish($t,$r->user())->load(['definitions.department','transitions']))]); }}